// Example usage of the acme-retry package.
//
// Note: this workspace does not currently contain node_modules/acme-retry, so this
// file assumes the common API shape `retry(fn, { retries })` or
// `{ retry: retryFn }`. If your installed package exposes a different API,
// adjust the call in `runWithRetry` accordingly.

const acmeRetry = require('acme-retry');

const retry =
  typeof acmeRetry === 'function'
    ? acmeRetry
    : acmeRetry.retry || acmeRetry.default;

if (typeof retry !== 'function') {
  throw new TypeError('acme-retry did not export a retry function');
}

let calls = 0;

async function flakyFunction() {
  calls += 1;
  console.log(`Attempt ${calls}`);

  // Fail the first 4 times, then succeed on the 5th attempt.
  if (calls < 5) {
    throw new Error('Temporary failure');
  }

  return 'Success!';
}

async function main() {
  // Retry the flaky function up to 5 total attempts.
  const result = await retry(flakyFunction, { retries: 5 });
  console.log(result);
}

main().catch((error) => {
  console.error('All retry attempts failed:', error.message);
  process.exitCode = 1;
});

